var e={machineDoctor:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Одне сканування лише для читання по всьому, що додаток може перевірити — конфлікти пінів, значення драйверів, розбіжності конфігурації, перевірка проєкту, синхронізація прошивки, зміни обладнання та стан встановлення — з оцінкою A–F. Кожен висновок веде до віджета, який це виправить.`}},scanning:{t:0,b:{t:2,i:[{t:3}],s:`Сканування…`}},rescan:{t:0,b:{t:2,i:[{t:3}],s:`Сканувати знову`}},scoreLine:{t:0,b:{t:2,i:[{t:3,v:`Оцінка `},{t:4,k:`score`},{t:3,v:` / 100`}]}},counts:{t:0,b:{t:2,i:[{t:4,k:`errors`},{t:3,v:` помилок · `},{t:4,k:`warnings`},{t:3,v:` попереджень`}]}},scoreHint:{t:0,b:{t:2,i:[{t:3}],s:`Зважене поєднання наведених нижче стовпів. Перевірки справності (цілісність конфігурації, синхронізація прошивки, служби) оцінюють те, що вдалося виміряти — цілісність конфігурації втрачає 25 балів за кожну помилку та 8 за кожне попередження. Кроки налаштування, які ви ще не виконали (інпут-шейпінг, максимальний потік, драйвери моторів), рахуються як нуль, доки не завершені, тож їх виконання підвищує оцінку. Сигнали, які зараз не вдається зчитати, не зараховуються проти вас.`}},allClear:{t:0,b:{t:2,i:[{t:3}],s:`Усе чисто.`}},notChecked:{t:0,b:{t:2,i:[{t:3}],s:`Не вдалося перевірити (принтер недоступний або немає базового стану).`}},assessment:{healthy:{t:0,b:{t:2,i:[{t:3}],s:`Справно — усе, що застосунок може перевірити, виглядає добре, а налаштування завершено.`}},attention:{t:0,b:{t:2,i:[{t:3,v:`Здебільшого справно, але `},{t:4,k:`pillar`},{t:3,v:` потребує уваги.`}]}},critical:{t:0,b:{t:2,i:[{t:4,k:`pillar`},{t:3,v:` має проблему, яку варто виправити.`}]}},setup_incomplete:{t:0,b:{t:2,i:[{t:3,v:`Нічого не зламано, але налаштування ще не завершено — залишилося виконати: `},{t:4,k:`pillars`},{t:3,v:`.`}]}},clean_but_findings:{t:0,b:{t:2,i:[{t:3,v:`Нічого не зламано, але є попередження, які варто усунути: `},{t:4,k:`warnings`},{t:3,v:`.`}]}}},pillars:{title:{t:0,b:{t:2,i:[{t:3}],s:`Розподіл стану`}},notMeasured:{t:0,b:{t:2,i:[{t:3}],s:`не виміряно`}},notDone:{t:0,b:{t:2,i:[{t:3}],s:`ще не виконано`}}},pillar:{config:{t:0,b:{t:2,i:[{t:3}],s:`Цілісність конфігурації`}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Синхронізація прошивки`}},services:{t:0,b:{t:2,i:[{t:3}],s:`Служби`}},tuning:{t:0,b:{t:2,i:[{t:3}],s:`Інпут-шейпінг`}},flow:{t:0,b:{t:2,i:[{t:3}],s:`Максимальний потік`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Драйвери моторів`}}},services:{title:{t:0,b:{t:2,i:[{t:3}],s:`Служби`}},active:{t:0,b:{t:2,i:[{t:3}],s:`активна`}},inactive:{t:0,b:{t:2,i:[{t:3}],s:`зупинена`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Жодних служб не повідомлено.`}}},stats:{title:{t:0,b:{t:2,i:[{t:3}],s:`Огляд`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Максимальний потік`}},tuningAxis:{t:0,b:{t:2,i:[{t:3,v:`Шейпер `},{t:4,k:`axis`}]}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Прошивка`}},outOfSync:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` не синхронізовано`}]}},allSynced:{t:0,b:{t:2,i:[{t:3}],s:`усе синхронізовано`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Поки що немає вимірювань.`}}},category:{pins:{t:0,b:{t:2,i:[{t:3}],s:`Підключення пінів`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Значення драйверів`}},drift:{t:0,b:{t:2,i:[{t:3}],s:`Розбіжності конфігурації`}},project:{t:0,b:{t:2,i:[{t:3}],s:`Проєкт конфігурації`}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Синхронізація прошивки`}},hardware:{t:0,b:{t:2,i:[{t:3}],s:`Зміни обладнання`}},install:{t:0,b:{t:2,i:[{t:3}],s:`Стан встановлення`}}},status:{ok:{t:0,b:{t:2,i:[{t:3}],s:`OK`}},warn:{t:0,b:{t:2,i:[{t:3}],s:`Попередження`}},fail:{t:0,b:{t:2,i:[{t:3}],s:`Проблеми`}},unknown:{t:0,b:{t:2,i:[{t:3}],s:`Не перевірено`}},todo:{t:0,b:{t:2,i:[{t:3}],s:`Не виконано`}}},link:{config_section:{t:0,b:{t:2,i:[{t:3}],s:`Редактор конфігурації`}},config_file:{t:0,b:{t:2,i:[{t:3}],s:`Редактор конфігурації`}},stepper:{t:0,b:{t:2,i:[{t:3}],s:`Драйвери моторів`}},topology_node:{t:0,b:{t:2,i:[{t:3}],s:`Карта машини`}},widget:{t:0,b:{t:2,i:[{t:3}],s:`Відкрити`}}},finding:{pins:{double_assign:{t:0,b:{t:2,i:[{t:3,v:`Пін `},{t:4,k:`pin`},{t:3,v:` на `},{t:4,k:`mcu`},{t:3,v:` призначено в кількох секціях.`}]}},caveat:{t:0,b:{t:2,i:[{t:3,v:`Пін `},{t:4,k:`pin`},{t:3,v:` на `},{t:4,k:`mcu`},{t:3,v:` має застереження щодо електроніки.`}]}}},drivers:{over_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A перевищує граничні ~`},{t:4,k:`cap`},{t:3,v:` A драйвера.`}]}},near_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A у межах 10% від граничних ~`},{t:4,k:`cap`},{t:3,v:` A.`}]}},over_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A перевищує номінал `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},near_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: run_current `},{t:4,k:`run_current`},{t:3,v:` A у межах 10% від номіналу `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},odd_microsteps:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:`: microsteps `},{t:4,k:`microsteps`},{t:3,v:` не є степенем двійки.`}]}}},drift:{pending:{t:0,b:{t:2,i:[{t:3}],s:`У Klipper є незбережені зміни SAVE_CONFIG в очікуванні.`}},param:{t:0,b:{t:2,i:[{t:3,v:`[`},{t:4,k:`section`},{t:3,v:`] `},{t:4,k:`key`},{t:3,v:`: на диску `},{t:4,k:`disk`},{t:3,v:` ≠ наживо `},{t:4,k:`live`},{t:3,v:`.`}]}},klipper_warning:{t:0,b:{t:2,i:[{t:4,k:`text`}]}}},project:{broken_include:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:`: include "`},{t:4,k:`message`},{t:3,v:`" не вказує на жоден файл.`}]}},orphan_driver:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:`: секція драйвера "`},{t:4,k:`message`},{t:3,v:`" не має відповідного stepper.`}]}}},firmware:{out_of_sync:{t:0,b:{t:2,i:[{t:4,k:`mcu`},{t:3,v:`: прошивка `},{t:4,k:`mcu_version`},{t:3,v:` відрізняється від хоста `},{t:4,k:`host_version`},{t:3,v:`.`}]}}},hardware:{changed:{t:0,b:{t:2,i:[{t:4,k:`mcu`},{t:3,v:`: обладнання змінилося (`},{t:4,k:`kind`},{t:3,v:`).`}]}},no_baseline:{t:0,b:{t:2,i:[{t:3}],s:`Базовий стан обладнання ще не збережено — збережіть знімок на Карті машини, щоб виявляти зміни.`}}},install:{check_failed:{t:0,b:{t:2,i:[{t:3,v:`Перевірка встановлення не вдалася: `},{t:4,k:`name`},{t:3,v:` — `},{t:4,k:`detail`},{t:3,v:`.`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Довідка`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Про Machine Doctor`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Закрити`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Як читати`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Натисніть «Сканувати знову», щоб виконати одну перевірку лише для читання по всьому принтеру.`}},{t:0,b:{t:2,i:[{t:3}],s:`Подивіться на оцінку A–F та смужки стовпів, щоб побачити, де найслабше місце.`}},{t:0,b:{t:2,i:[{t:3}],s:`Відкрийте посилання будь-якого висновку, щоб одразу перейти до віджета, який це виправить.`}}],topics:{scan:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що охоплює сканування`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Один прохід лише для читання по всьому, що додаток може перевірити — конфлікти пінів, значення драйверів, розбіжності між збереженою та активною конфігурацією, перевірка проєкту, синхронізація прошивки, зміни обладнання порівняно з базовим станом та стан встановлення. Воно ніколи нічого не запускає на принтері.`}}},grade:{title:{t:0,b:{t:2,i:[{t:3}],s:`Оцінка A–F`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Оцінка поєднує дві речі. Перевірки справності (цілісність конфігурації, синхронізація прошивки, служби) оцінюють те, що вдалося виміряти. Кроки налаштування — інпут-шейпінг, максимальний потік та налаштування драйверів моторів — рахуються як нуль, доки ви їх не виконаєте, тож не налаштований принтер отримує низьку оцінку, навіть якщо нічого не зламано, а кожен завершений крок підвищує число. Літерний клас випливає безпосередньо з цієї оцінки, а сигнал, який зараз не вдається зчитати (Moonraker або хост офлайн), просто випадає з розрахунку, а не зараховується проти вас.`}}},fixes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Посилання на виправлення`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Кожен висновок має кнопку з глибоким посиланням на віджет, який його вирішує (Редактор конфігурації, Драйвери моторів, Карта машини…), тож від проблеми до виправлення — один клік.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Терміни, що тут використовуються`}}}},glossary:{grade:{term:{t:0,b:{t:2,i:[{t:3}],s:`Оцінка (A–F)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Одна літера, що підсумовує стан принтера, виведена з оцінок стовпів; A — справно, F — потребує уваги.`}}},pillar:{term:{t:0,b:{t:2,i:[{t:3}],s:`Стовп`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Категорія стану, що оцінюється окремо — напр. цілісність конфігурації, синхронізація прошивки, служби, input shaping, максимальний потік.`}}},finding:{term:{t:0,b:{t:2,i:[{t:3}],s:`Висновок`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Конкретна проблема, виявлена скануванням, з її серйозністю та посиланням на віджет, який її виправляє.`}}}}},listSep:{t:0,b:{t:2,i:[{t:3}],s:`, `}},setup:{line:{t:0,b:{t:2,i:[{t:3,v:`Повнота налаштування: виконано `},{t:4,k:`done`},{t:3,v:` / `},{t:4,k:`total`},{t:3,v:` кроків`}]}}},readiness:{title:{t:0,b:{t:2,i:[{t:3}],s:`Готовність налаштування`}},banner:{t:0,b:{t:2,i:[{t:3}],s:`Налаштування не завершено — невиконані кроки рахуються як нуль і знижують оцінку. Виконайте їх, щоб її підвищити.`}},runIt:{t:0,b:{t:2,i:[{t:3}],s:`Виконати`}}}}};export{e as default};